-- 把 todo/plan 类型的片段登记进待办表（模拟确认时的登记行为，否则跨日记待办追踪无数据）
INSERT INTO todo_registry (user_id, title, current_status, source_chunk_id)
SELECT c.user_id,
       COALESCE(c.metadata->>'title', LEFT(c.segment, 40)),
       COALESCE(c.metadata->>'taskStatus', 'not_started'),
       c.id
FROM chunks c
WHERE c.user_id = '2c6bb470-2c15-43f0-8ac9-2c9f3c7ee032'
  AND c.metadata->>'contentType' IN ('todo', 'plan')
  AND NOT EXISTS (SELECT 1 FROM todo_registry t WHERE t.source_chunk_id = c.id);

-- origin 关联（登记时的原始片段）
INSERT INTO todo_registry_links (todo_id, chunk_id, relation)
SELECT t.id, t.source_chunk_id, 'origin'
FROM todo_registry t
WHERE t.user_id = '2c6bb470-2c15-43f0-8ac9-2c9f3c7ee032'
  AND t.source_chunk_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM todo_registry_links l
                   WHERE l.todo_id = t.id AND l.chunk_id = t.source_chunk_id);

-- 把序列推到最大值之后，避免后续插入撞主键
SELECT setval('records_id_seq',       (SELECT COALESCE(MAX(id), 1) FROM records));
SELECT setval('chunks_id_seq',        (SELECT COALESCE(MAX(id), 1) FROM chunks));
SELECT setval('todo_registry_id_seq', (SELECT COALESCE(MAX(id), 1) FROM todo_registry));